def add(d,num,extra,body,tree):
    aliases=dict(base, **dict(i.split('=',1) for i in extra.strip().splitlines() if i))
    per={}; nodes=[]
    for row in body.strip().splitlines():
        if not row.strip(): continue
        n,scope,*items=row.split(); n=int(n); nodes.append({'node':f'n{n}','scope':[scopes[c] for c in scope]}); per[n]=defaultdict(dict)
        for item in items:
            path,rr=item.split(':'); path=aliases.get(path,path)
            for spec in rr.split(','):
                m=re.fullmatch(r'(\d+)(?:-(\d+))?([DUI]+)',spec); assert m,(d,n,item,spec)
                a,b,r=m.groups(); a=int(a); b=int(b or a); assert a<=b
                for line in range(a,b+1): per[n][path][line]=per[n][path].get(line,set())|set(r)
    assert [int(x['node'][1:]) for x in nodes]==list(range(1,num+1)),(d,nodes)
    for p,children in tree.items():
        for ch in children:
            for path,lines in per[ch].items():
                for line,r in lines.items(): per[p][path][line]=per[p][path].get(line,set())|r
    mappings=[]
    for n,files in per.items():
        for path,lines in sorted(files.items()):
            def emit(a,b,r):
                mappings.append({'node':f'n{n}','path':path,'startLine':a,'endLine':b,'role':[roles[c] for c in roles if c in r]})
            # Contiguous ranges of the same role; preserve exact role boundaries.
            a=b=None; r=None
            for l,rr in sorted(lines.items()):
                if b is not None and (l!=b+1 or rr!=r): emit(a,b,r); a=None
                if a is None: a=l; r=rr
                b=l
            if a is not None: emit(a,b,r)
    Ds.append(dict(diagramId=f'd{d}',nodes=nodes,mappings=mappings))
